// 4. Directive Validation Node
let directives = [];
try {
  const candidates = $input.item.json.candidates || [];
  const rawText = candidates[0]?.content?.parts[0]?.text || '{"directives": []}';
  const parsed = JSON.parse(rawText);
  directives = parsed.directives || [];
} catch (e) {
  directives = [{ directive_type: 'no_op', hours: [] }];
}

// Enforce validation bounds
const validDirectives = directives.filter(d => {
  if (!['solar_reduction', 'minimum_battery_reserve', 'no_charge_window', 'no_discharge_window', 'max_grid_window', 'no_op'].includes(d.directive_type)) return false;
  if (Array.isArray(d.hours)) {
    d.hours = d.hours.filter(h => h >= 0 && h <= 23);
  }
  return true;
});

const scenario = $('2. Input Validation').item.json.scenario;
const prompt = $('2. Input Validation').item.json.prompt;

return {
  json: {
    directives: validDirectives,
    scenario: scenario,
    raw_prompt: prompt
  }
};
